import { z } from 'zod/v4';
import { MedicationSchema } from './medication';
import { OrderTypeSchema } from './orderType';
import { BasicString, EhrId } from '../primitives';

export const CreateOrderSchema = z.object({
  id: EhrId.optional(),
  type: OrderTypeSchema.optional(),
  name: BasicString.optional(),
  modality: BasicString.optional(),
  category: BasicString.optional(),
  description: BasicString.optional(),
  status: BasicString.optional(),
  encounterId: EhrId.optional(),
  medications: z.array(MedicationSchema).optional(),
});

export type CreateOrder = z.infer<typeof CreateOrderSchema>;
