import { WebConnectors } from '../..';
import { WebConnectorMessageTypes } from '../../enum';
import {
  RemoveAudioMediaRecorderInput,
  RemoveAudioMediaRecorderResponse,
} from '../../types/mediaRecorder';

export async function removeAudioMediaRecorder(
  this: WebConnectors,
  { subscriptionId, appId }: RemoveAudioMediaRecorderInput,
): Promise<RemoveAudioMediaRecorderResponse> {
  return await this.messaging.sendMessage({
    type: WebConnectorMessageTypes.removeAudioMediaRecorder,
    payload: { subscriptionId, appId },
  });
}
