import { createSelector } from '@reduxjs/toolkit';
import { RootState } from '..';
import { selectApplications } from './appListening.selectors';

/**
 * Base selector to get user management state from the applications state
 * @param state - The root Redux state
 * @returns User management state object
 */
const selectUserManagementState = (state: RootState) => state.applicationsState.userManagement;

/**
 * Memoized selector to get user management notification badge count
 * @param state - The root Redux state
 * @returns Number of notifications from user management
 */
export const selectUserManagementNotificationBadge = createSelector(
  [selectUserManagementState],
  (userManagement = {}) => userManagement.notificationBadge,
);

/**
 * Memoized selector to get total notifications count from all applications
 * @param state - The root Redux state
 * @returns Total number of notifications from all applications
 */
export const selectTotalAppNotifications = createSelector([selectApplications], (applications) =>
  Object.values(applications).reduce((sum, app) => sum + (app?.notifications ?? 0), 0),
);

/**
 * Memoized selector to get total notifications count including user management
 * @param state - The root Redux state
 * @returns Total number of notifications from all sources
 */
export const selectTotalNotifications = createSelector(
  [selectTotalAppNotifications, selectUserManagementNotificationBadge],
  (appNotifications = 0, userManagementNotifications = 0) =>
    appNotifications + userManagementNotifications,
);

/**
 * Memoized selector to check if all applications have clear notifications indicator
 * @param state - The root Redux state
 * @returns Boolean indicating if all apps have clear notifications indicator
 */
export const selectAllAppsClearNotificationsIndicator = createSelector(
  [selectApplications],
  (applications) => Object.values(applications).every((app) => app.clearNotificationsIndicator),
);

/**
 * Memoized selector to check if user management has clear notifications indicator
 * @param state - The root Redux state
 * @returns Boolean indicating if user management has clear notifications indicator
 */
export const selectUserManagementClearNotificationsIndicator = createSelector(
  [selectUserManagementState],
  (userManagement = {}) =>
    !userManagement.notificationBadge && !userManagement.showEmptyNotification,
);

/**
 * Memoized selector to check if all notifications should be cleared
 * @param state - The root Redux state
 * @returns Boolean indicating if all notifications should be cleared
 */
export const selectAllNotificationsCleared = createSelector(
  [selectAllAppsClearNotificationsIndicator, selectUserManagementClearNotificationsIndicator],
  (allAppsCleared, userManagementCleared) => allAppsCleared && userManagementCleared,
);

/**
 * Memoized selector to check if hub should be active based on applications
 * @param state - The root Redux state
 * @returns Boolean indicating if hub should be active (has active apps)
 */
export const selectHubIsActive = createSelector([selectApplications], (applications) =>
  Object.values(applications).some(
    (app) => !app.loading && !app.disabled && app.affectVimHubTurnedOn,
  ),
);
