import { WebConnectors } from '../..';
import { WebConnectorMessageTypes } from '../../enum';
import { CreateGlobalWebRTCMediaRecorderInput } from '../../types/mediaRecorder';

export async function createGlobalWebRTCMediaRecorder(
  this: WebConnectors,
  { handlerPort, appId, timeslice = 1000 }: CreateGlobalWebRTCMediaRecorderInput,
): Promise<{ subscriptionId: string }> {
  return await this.messaging.sendMessageWithHandlerPort(
    {
      type: WebConnectorMessageTypes.createGlobalWebRTCMediaRecorder,
      payload: { handlerPort, appId, timeslice },
    },
    handlerPort,
  );
}
