import { z } from 'zod/v4';
import {
  DiagnosisSchema,
  ProcedureSchema,
  ProviderSchema,
  ReferralPrioritySchema,
  SpecialtySchema,
} from '../../entities/sub-entities';
import { BasicString, IsoDate } from '../../entities/primitives';

export const UpdateReferralSchema = z.object({
  specialty: SpecialtySchema.optional(),
  diagnosis: z.array(DiagnosisSchema).optional(),
  reasons: z.array(BasicString).optional(),
  startDate: IsoDate.optional(),
  endDate: IsoDate.optional(),
  notes: BasicString.optional(),
  priority: ReferralPrioritySchema.optional(),
  cpts: z.array(ProcedureSchema).optional(),
  numberOfVisits: BasicString.optional(),
  authCode: BasicString.optional(),
  targetProvider: ProviderSchema.optional(),
  referringProvider: ProviderSchema.optional(),
});

export type UpdateReferral = z.infer<typeof UpdateReferralSchema>;

const ProviderToWriteBackSchema = ProviderSchema.omit({ providerEhrId: true });

export const UpdateReferralWritebackInputSchema = UpdateReferralSchema.pick({
  specialty: true,
  diagnosis: true,
  reasons: true,
  startDate: true,
  endDate: true,
  notes: true,
  priority: true,
  cpts: true,
  numberOfVisits: true,
  authCode: true,
})
  .extend({
    targetProvider: ProviderToWriteBackSchema,
  })
  .partial();
