import { z } from 'zod/v4';
import { BasicString } from './primitives';

export const FirstName = z
  .string()
  .min(1)
  .meta({
    kind: 'firstName',
    examples: ['Jake'],
    description: 'Given name',
  });

export const MiddleName = z
  .string()
  .min(1)
  .meta({
    kind: 'middleName',
    examples: ['A'],
    description: 'Middle name',
  });

export const LastName = z
  .string()
  .min(1)
  .meta({
    kind: 'lastName',
    examples: ['Ginsbach'],
    description: 'Family name',
  });

export const OrgName = z
  .string()
  .min(1)
  .meta({
    kind: 'orgName',
    examples: ['7 Hills Department'],
    description: 'Provider organization name',
  });

export const Degree = BasicString.meta({
  kind: 'degree',
  examples: ['MD', 'DO', 'NP'],
  description: 'Medical professional degree',
});
