import { OsState } from '@/store';
import {
  ActionNames,
  PatientAction,
  PatientMedicationAction,
  PatientAllergyAction,
  PatientLabResultsAction,
  PatientVitalsAction,
} from '@getvim-os/types/actions';
import { inject, injectable } from 'inversify';
import { ActionsManager } from './actionsManager';
import { VimSpan } from '@getvim/opentelemetry-sdk/client';
import { CancelledRequestError } from '@getvim-os/errors';
import { ExecuteResourceEnhancementPayload } from '@getvim/vim-os-api';
import { PaginationInput } from '@getvim-os/types';

@injectable()
export class ResourceEnhancementsManager {
  constructor(
    @inject(ActionsManager) private actionsManager: ActionsManager,
    @inject(OsState) private osState: OsState,
  ) {}

  public async getPatientProblemList({
    appId,
    span,
  }: {
    payload: ExecuteResourceEnhancementPayload;
    appId: string;
    span: VimSpan;
  }) {
    const patient = await this.actionsManager.executeActionPromised<
      PatientAction.Input,
      PatientAction.Response
    >(
      ActionNames.GET_PATIENT,
      {
        patientId: this.getPatientId(),
        disableCache: true,
        refreshProblemList: true,
      },
      appId,
      span,
    );

    return patient.problemList;
  }

  public async getPatientMedicationList({
    appId,
    span,
  }: {
    payload: ExecuteResourceEnhancementPayload;
    appId: string;
    span: VimSpan;
  }) {
    const medicationList = await this.actionsManager.executeActionPromised<
      PatientMedicationAction.Input,
      PatientMedicationAction.Response
    >(
      ActionNames.GET_PATIENT_MEDICATION,
      {
        patientId: this.getPatientId(),
      },
      appId,
      span,
    );

    return medicationList.medications;
  }

  public async getPatientAllergyList({
    appId,
    span,
  }: {
    payload: ExecuteResourceEnhancementPayload;
    appId: string;
    span: VimSpan;
  }) {
    const allergyList = await this.actionsManager.executeActionPromised<
      PatientAllergyAction.Input,
      PatientAllergyAction.Response
    >(
      ActionNames.GET_PATIENT_ALLERGIES,
      {
        patientId: this.getPatientId(),
      },
      appId,
      span,
    );

    return allergyList.allergies;
  }

  public async getPatientLabResults({
    appId,
    span,
    payload,
  }: {
    payload: ExecuteResourceEnhancementPayload;
    appId: string;
    span: VimSpan;
  }) {
    const labResultsPayload = payload as Extract<
      ExecuteResourceEnhancementPayload,
      { enhancement: 'getLabResults' }
    >;

    return await this.actionsManager.executeActionPromised<
      PaginationInput & { patientId: string },
      PatientLabResultsAction.Response
    >(
      ActionNames.GET_PATIENT_LAB_RESULTS,
      {
        ...labResultsPayload.input[0],
        patientId: this.getPatientId(),
      },
      appId,
      span,
    );
  }

  public async getPatientVitals({
    appId,
    span,
    payload,
  }: {
    payload: ExecuteResourceEnhancementPayload;
    appId: string;
    span: VimSpan;
  }) {
    const vitalsPayload = payload as Extract<
      ExecuteResourceEnhancementPayload,
      { enhancement: 'getVitals' }
    >;

    return await this.actionsManager.executeActionPromised<
      PaginationInput & { patientId: string },
      PatientVitalsAction.Response
    >(
      ActionNames.GET_PATIENT_VITALS,
      {
        ...vitalsPayload.input[0],
        patientId: this.getPatientId(),
      },
      appId,
      span,
    );
  }

  public validatePatientState(payload: ExecuteResourceEnhancementPayload) {
    if (
      this.osState.store.getState().ehrState.patient?.token !== payload.resourceId &&
      this.osState.store.getState().ehrState.patient?.vimPatientId !== payload.resourceId
    ) {
      throw new CancelledRequestError('Current patient is different than requested enhancement', {
        enhancement: payload.enhancement,
        resourceId: payload.resourceId,
      });
    }
  }

  private getPatientId() {
    return this.osState.store.getState().ehrState.patient!.patientId;
  }
}
