import { z } from 'zod/v4';
import { BasicString } from './primitives';

/** IDs */
export const EhrId = BasicString.min(1).meta({ kind: 'id', description: 'Opaque EHR identifier' });
export const EncounterId = BasicString.min(1).meta({
  kind: 'id',
  description: 'Encounter EHR identifier',
});
export const PatientId = BasicString.min(1).meta({
  kind: 'id',
  description: 'Patient EHR identifier',
});
export const AppointmentId = BasicString.min(1).meta({
  kind: 'id',
  description: 'Appointment EHR identifier',
});
export const ProviderEhrId = BasicString.min(1).meta({
  kind: 'id',
  description: 'Provider EHR id',
});
export const FacilityEhrId = BasicString.min(1).meta({
  kind: 'id',
  description: 'Facility EHR id',
});

export const NPI = z
  .string()
  .regex(/^\d{10}$/)
  .meta({
    examples: ['1234567890'],
    description: 'US 10-digit NPI',
    kind: 'npi',
  });

/** Medical codes */
export const NdcCode = BasicString.meta({
  examples: ['12345-6789-01'],
  description: 'National Drug Code',
  kind: 'ndc',
});

export const LoincCode = BasicString.meta({
  kind: 'loincCode',
  examples: ['55284-4'],
  description:
    'Logical Observation Identifiers Names and Codes, universal standard for identifying laboratory tests and observations',
});

export const DiagnosisCode = BasicString.meta({
  kind: 'dxCode',
  examples: ['E11.9'],
  description: 'ICD-10-CM diagnosis code',
});

export const ProcedureCode = BasicString.meta({
  kind: 'cptCode',
  examples: ['99213'],
  description: 'CPT/HCPCS procedure code',
});

export const TaxonomyCode = z
  .string()
  .meta({ kind: 'taxonomyCode', examples: ['170300000X'], description: 'Provider taxonomy code' });

export const CodeDescription = BasicString.meta({
  kind: 'codeDescription',
  description: 'description of medical code (icd/cpt)',
  examples: ['Essential (primary) hypertension', 'Expanded problem-focused examination'],
});
