import { WebConnectors } from '../..';
import { WebConnectorMessageTypes } from '../../enum';

type GetWebRTCStreamStateResult = {
  readyState: 'live' | 'ended';
  enabled: boolean;
  kind: string;
  id: string;
  label: string;
};

export function getWebRTCStreamState(
  this: WebConnectors,
): Promise<GetWebRTCStreamStateResult | null> {
  return this.messaging.sendMessage({ type: WebConnectorMessageTypes.getWebRTCStreamState });
}
