import { inject, injectable } from 'inversify';
import { v4 as uuid } from 'uuid';
import {
  SendMessageInput,
  PARENT_COMMUNICATOR,
  ParentCommunicator,
  ParentMessage,
  BareboneMessageHandler,
} from './types';
import type { VimSpan } from '@getvim/opentelemetry-sdk/client';
import {
  BareboneToOsMessaging,
  BareboneManifest,
  OSToBareboneMessaging,
} from '@getvim/ehr-sdk-api';

export { PARENT_COMMUNICATOR, type BareboneMessageHandler } from './types';
export type { ParentMessage, FrameSource, ParentCommunicator } from './types';
export * from './parent-communicators';

interface SendMessageWithHandlerInput<T> extends SendMessageInput {
  handler: (data: T, isError: boolean) => void;
}

@injectable()
export class BareboneMessaging {
  @inject(PARENT_COMMUNICATOR) private parentCommunicator!: ParentCommunicator;

  public async setupMessaging(): Promise<BareboneManifest | void> {
    return await this.parentCommunicator.setup(this.getTabIdFromUrl());
  }

  public onParentMessages(callback: (parentMessage: ParentMessage) => void) {
    return this.parentCommunicator.onParentMessage(callback);
  }

  public async sendAwaitedMessage<T extends OSToBareboneMessaging.OSMessageTypes>(
    { type, payload, timeout }: OSToBareboneMessaging.OSMessage<T> & { timeout?: number },
    parentSpan?: VimSpan,
  ): Promise<{ success?: boolean; error?: any } | undefined> {
    return await this.parentCommunicator.sendMessage(
      {
        type,
        payload,
        ...this.getMessageMetadata(),
      },
      timeout,
      parentSpan,
    );
  }

  public sendRawMessage(message: object, ports?: ReadonlyArray<MessagePort>): void {
    const rawMessage = {
      ...this.getMessageMetadata(),
      ...message,
    };
    this.parentCommunicator.sendRawMessage(rawMessage, ports);
  }

  public addBareboneMessageHandler<T extends BareboneToOsMessaging.BareboneMessageTypes>(
    eventType: T,
    handler: BareboneMessageHandler<T>,
  ): void {
    this.parentCommunicator.addBareboneMessageHandler(eventType, handler);
  }

  public sendMessageWithHandlerPort(
    { type, payload, ehrInstanceId, timeout }: SendMessageInput,
    handlerPort: MessagePort,
  ): Promise<any> {
    return this.parentCommunicator.sendMessageWithHandlerPort(
      {
        type,
        payload,
        ...this.getMessageMetadata(),
        ...(ehrInstanceId ? { ehrInstanceId } : {}),
      },
      handlerPort,
      timeout,
    );
  }

  public sendAsyncMessage({ type, payload, ehrInstanceId }: SendMessageInput): void {
    this.parentCommunicator.sendAsyncMessage({
      type,
      payload,
      ...this.getMessageMetadata(),
      ...(ehrInstanceId
        ? {
            ehrInstanceId,
          }
        : {}),
    });
  }

  public async sendMessage<RETURN = unknown>(
    { type, payload, ehrInstanceId, timeout }: SendMessageInput,
    parentSpan?: VimSpan,
  ): Promise<RETURN> {
    return await this.parentCommunicator.sendMessage(
      {
        type,
        payload,
        ...this.getMessageMetadata(),
        ...(ehrInstanceId
          ? {
              ehrInstanceId,
            }
          : {}),
      },
      timeout,
      parentSpan,
    );
  }

  public async sendMessageWithHandler<T>({
    type,
    payload,
    handler,
    ehrInstanceId,
    timeout,
  }: SendMessageWithHandlerInput<T>): Promise<string> {
    return await this.parentCommunicator.sendMessageWithHandler(
      {
        type,
        payload,
        ...this.getMessageMetadata(),
        ...(ehrInstanceId
          ? {
              ehrInstanceId,
            }
          : {}),
      },
      handler,
      timeout,
    );
  }

  private getMessageMetadata() {
    return {
      messageId: uuid(),
      ehrInstanceId: this.getTabIdFromUrl(),
    };
  }

  private getTabIdFromUrl() {
    const url = new URL(window.location.href);
    const tabId = url.searchParams.get('tabId');
    const pid = url.searchParams.get('pid');
    return tabId ? Number(tabId) : pid ? Number(pid) : undefined;
  }
}
