import { WebConnectors } from '../..';
import { WebConnectorMessageTypes } from '../../enum';

export async function subscribeToEHREvent(
  this: WebConnectors,
  { handlerPort }: { handlerPort: MessagePort },
): Promise<void> {
  return await this.messaging.sendMessageWithHandlerPort(
    {
      type: WebConnectorMessageTypes.subscribeToEHREvent,
    },
    handlerPort,
  );
}
