import { injectable } from 'inversify';
import { Analytics, TrackPayload } from '@getvim/analytics';

@injectable()
export class AnalyticsManager {
  private analyticsClient = new Analytics();
  private userId: string | null = null;

  async setUserId(userId: string | null): Promise<void> {
    // avoids reset in case the id was not changed
    if (this.userId === userId) {
      return;
    }

    this.userId = userId;
    await this.analyticsClient.reset();
    await this.analyticsClient.identify(userId);
  }

  track(params: TrackPayload): void {
    this.analyticsClient.track({
      ...params,
      userId: this.userId,
      // set mix panel "$device_id" property
      anonymousId: 'guest',
    });
  }
}
