import { inject, injectable } from 'inversify';
import { CommonConnectors } from '../connectors';
import type { VimSpan } from '@getvim/opentelemetry-sdk/client';
import { StorageKnownKey } from './types';

interface StorageSchema extends Partial<Record<StorageKnownKey, any>> {
  [StorageKnownKey.VIM_TOKENS]: Partial<
    Record<
      string,
      {
        accessToken?: string;
        refreshToken?: string;
        tokensTimeMetadata?: { clientTime: string; serverTime: string };
      }
    >
  >;
  [StorageKnownKey.VIM_PASSWORD_SALT]: Partial<Record<string, string>>;
  [StorageKnownKey.OVERRIDE_ORGANIZATION]: string;
  [StorageKnownKey.ORGANIZATION_KEY]: string;
  [StorageKnownKey.SDK_USER_INFO]: { clinicId: string } | undefined;
  [StorageKnownKey.SIGNUP_SESSION_ID]: string;
  [StorageKnownKey.USER_MANAGEMENT_STORAGE_KEY]: {
    notifications: Record<
      string,
      {
        lastShowDate: string;
        numberOfShows: number;
      }
    >;
  };
}

@injectable()
export class BareboneStorage {
  constructor(@inject(CommonConnectors) private commonConnectors: CommonConnectors) {}

  /**
   * @deprecated Use getItem<StorageType<K>>(key) instead
   */
  async get<T = unknown>(key: string, parentSpan?: VimSpan): Promise<T> {
    const value = await this.commonConnectors.storageGet({ key }, parentSpan);
    return value?.[key];
  }

  async getItem<K extends StorageKnownKey>(
    key: K,
    parentSpan?: VimSpan,
  ): Promise<StorageSchema[K] | undefined> {
    const value = await this.commonConnectors.storageGet<Record<K, StorageSchema[K] | undefined>>(
      {
        key,
      },
      parentSpan,
    );
    return value?.[key];
  }

  set(key: string, value: unknown, parentSpan?: VimSpan): Promise<void> {
    return this.commonConnectors.storageSet(
      {
        data: { [key]: value },
      },
      parentSpan,
    );
  }

  setItem<K extends StorageKnownKey>(
    key: K,
    value: StorageSchema[K],
    parentSpan?: VimSpan,
  ): Promise<void> {
    return this.commonConnectors.storageSet({ data: { [key]: value } }, parentSpan);
  }

  remove(key: string, parentSpan?: VimSpan): Promise<void> {
    return this.set(key, null, parentSpan);
  }

  async safeGet<T>(key: string, logger?): Promise<Record<string, T>> {
    let value: Record<string, T> = {};
    try {
      const res = await this.get<Record<string, T>>(key);
      if (res != undefined && res != null) {
        value = res;
      }
    } catch (error) {
      (logger || console).error('error when fetching overrides from storage', {
        errorMessage: (error as Error).message,
      });
    }
    return value;
  }
}
