import { injectable, inject } from 'inversify';
import { createPromisedChannel } from 'msg-channel-shake/core';
import { ActionNames } from '@getvim-os/types';
import { OsMessageChannelManager } from '../deprecated/runtime-wrapper/osMessageChannelManager';
import { Events } from '@deprecated/types';
import { VimSpan } from '@getvim/opentelemetry-sdk/client';
import { OsToRuntimeMetadata } from '@/deprecated/types/events/eventsBetweenOsRuntime';
import { UnprocessableEntityError } from '@getvim-os/errors';

@injectable()
export class ActionsManager {
  private DEFAULT_ACTION_TIMEOUT_MS: number = 30_000;

  constructor(
    @inject(OsMessageChannelManager) private osMessageChannelManager: OsMessageChannelManager,
  ) {}

  public async executeActionPromised<TInput, TResponse>(
    action: ActionNames,
    input: TInput,
    sender: string,
    span: VimSpan,
    handlerPort?: MessagePort,
  ): Promise<TResponse> {
    const [portToForward, promise] = createPromisedChannel<TResponse>(
      this.DEFAULT_ACTION_TIMEOUT_MS,
    );
    this.executeAction(
      action,
      input,
      { sender, traceId: span.spanContext().traceId },
      portToForward,
      handlerPort,
    );

    try {
      return await span.startAutoChildSpan('executeAction', {}, () => promise);
    } catch (error: any) {
      if (error?.includes('not supported')) {
        throw new UnprocessableEntityError('NOT_SUPPORTED_IN_EHR_SYSTEM');
      }
      const message = `Error while getting result from action ${action}!`;
      if (error?.message) {
        throw new Error(`${message} ${error?.message}`, {
          cause: error,
        });
      }
      if (typeof error === 'string') {
        // eslint-disable-next-line unicorn/prefer-type-error
        throw new Error(`${message} ${error}`, {
          cause: error,
        });
      }
      throw new Error(message, { cause: error });
    }
  }

  public executeAction(
    action: ActionNames,
    input: unknown,
    metadata: OsToRuntimeMetadata,
    responseMessagePort: MessagePort,
    handlerPort?: MessagePort,
  ) {
    try {
      this.osMessageChannelManager.sendMessageToRuntime(
        {
          type: Events.OsToRuntimeEvents.EXECUTE_ACTION,
          payload: {
            action,
            input,
            metadata,
          },
        },
        handlerPort ? [responseMessagePort, handlerPort] : [responseMessagePort],
      );
    } catch (error) {
      responseMessagePort.postMessage({
        error: true,
        response: (error as Error)?.message,
      });

      return;
    }
  }
}
