import { z } from 'zod/v4';
import { BaseDemographicsSchema } from './baseDemographics';
import { OrganizationSchema } from './organization';
import { SpecialtySchema } from './specialty';
import { Degree, NPI, ProviderEhrId } from '../primitives';

const ProviderTypeSchema = z.enum(['PROVIDER', 'FACILITY']);

export const BasicProviderSchema = z.object({
  providerEhrId: ProviderEhrId,
  npi: NPI.optional(),
  demographics: BaseDemographicsSchema,
  organization: OrganizationSchema.optional(),
  specialty: z.array(SpecialtySchema).optional(),
  degree: Degree.optional(),
});

export type BasicProvider = z.infer<typeof BasicProviderSchema>;

export const ProviderSchema = BasicProviderSchema.extend({
  organizations: z
    .array(OrganizationSchema)
    .optional()
    .describe('@deprecated - Use organization instead'),
});

// ProviderSchema type with optional demographics based on ProviderSchema
export const ProviderWithOptionalDemographicsSchema = z.object({
  ...ProviderSchema.shape,
  type: ProviderTypeSchema.describe(
    'Distinct if the provider contains individual provider on the facility',
  ),
  demographics: BaseDemographicsSchema.optional().describe(
    'Optional demographics for the provider on the facility',
  ),
});

export type Provider = z.infer<typeof ProviderSchema>;

export type ProviderWithOptionalDemographics = z.infer<
  typeof ProviderWithOptionalDemographicsSchema
>;

// Convert the provider to the legacy provider schema
// TODO: Remove this function when all system is aligned with the new provider schema
export const ProviderConverter = (
  provider: ProviderWithOptionalDemographics | undefined,
): Provider | undefined => {
  if (!provider) {
    return undefined;
  }
  const providerLegacy: Provider = {
    providerEhrId: provider.providerEhrId,
    demographics: provider.demographics ?? {
      firstName: provider.organization?.name ?? 'Organization',
      lastName: 'Organization',
    },
    npi: provider.npi,
    organization: provider.organization,
    specialty: provider.specialty,
    degree: provider.degree,
    organizations: provider.organizations,
  };
  return providerLegacy;
};
