import { VimSpan } from '@getvim/opentelemetry-sdk/client';
import { ApplicationManifest, EHRResource, PatientEnhancements } from '@getvim-os/types';
import { ExecuteResourceEnhancementPayload } from '@getvim/vim-os-api';
import { InvalidInputError, RateLimitError, UnauthorizedError } from '@getvim-os/errors';
import { inject, injectable } from 'inversify';
import { AdapterManager } from '../../adapter-manager/adapterManager';
import { RateLimiter } from 'limiter';
import { AppLimiter } from './applicationState.service';
import { didAppReachLimit } from './rateLimiter';
export interface ResourceEnhancementHelper {
  enhancements: {
    [key: string]: {
      executeEnhancement: ({
        payload,
        appId,
        span,
        manifest,
      }: {
        payload: ExecuteResourceEnhancementPayload;
        appId: string;
        span: VimSpan;
        manifest: ApplicationManifest | undefined;
      }) => Promise<unknown>;
    };
  };
}

@injectable()
export class ResourceEnhancersHandlerProvider {
  private appProblemListActionsLimiter: AppLimiter = new Map<string, RateLimiter>();
  private appMedicationListActionsLimiter: AppLimiter = new Map<string, RateLimiter>();
  private appAllergyListActionsLimiter: AppLimiter = new Map<string, RateLimiter>();
  private appLabResultsActionsLimiter: AppLimiter = new Map<string, RateLimiter>();
  private appVitalsActionsLimiter: AppLimiter = new Map<string, RateLimiter>();
  constructor(@inject(AdapterManager) private adapterManager: AdapterManager) {}

  private validateResource(payload: ExecuteResourceEnhancementPayload) {
    this.adapterManager.resourceEnhancementsManager.validatePatientState(payload);
  }

  getResourceEnhancementHelper({
    ehrResource,
  }: {
    ehrResource: string;
  }): ResourceEnhancementHelper {
    switch (ehrResource as EHRResource) {
      case EHRResource.patient:
        return this.patientResourceEnhancementHandler;
      default:
        throw new InvalidInputError(`Resource ${ehrResource} is not supported`);
    }
  }

  private patientResourceEnhancementHandler: ResourceEnhancementHelper = {
    enhancements: {
      [PatientEnhancements.GET_PROBLEM_LIST]: {
        executeEnhancement: async (input) => {
          const patientPermissions = input.manifest?.EHR.resourcePermissions?.[EHRResource.patient];
          if (!patientPermissions?.problemList?.read) {
            throw new UnauthorizedError(
              `Application ${input.appId} is not allowed to perform enhancement getProblemList, please update the application manifest & get it approved.`,
            );
          }
          this.validateResource(input.payload);
          if (didAppReachLimit(input.appId, this.appProblemListActionsLimiter)) {
            throw new RateLimitError(
              "Reached enhancements quota, You're not allowed to execute more than 10 enhancements in a minute, please try again later.",
            );
          }

          return await this.adapterManager.resourceEnhancementsManager.getPatientProblemList(input);
        },
      },
      [PatientEnhancements.GET_MEDICATION_LIST]: {
        executeEnhancement: async (input) => {
          const patientPermissions = input.manifest?.EHR.resourcePermissions?.[EHRResource.patient];
          if (!patientPermissions?.medicationList?.read) {
            throw new UnauthorizedError(
              `Application ${input.appId} is not allowed to perform enhancement getMedicationList, please update the application manifest & get it approved.`,
            );
          }
          this.validateResource(input.payload);
          if (didAppReachLimit(input.appId, this.appMedicationListActionsLimiter)) {
            throw new RateLimitError(
              "Reached enhancements quota, You're not allowed to execute more than 10 enhancements in a minute, please try again later.",
            );
          }

          return await this.adapterManager.resourceEnhancementsManager.getPatientMedicationList(
            input,
          );
        },
      },
      [PatientEnhancements.GET_ALLERGY_LIST]: {
        executeEnhancement: async (input) => {
          const patientPermissions = input.manifest?.EHR.resourcePermissions?.[EHRResource.patient];
          if (!patientPermissions?.allergyList?.read) {
            throw new UnauthorizedError(
              `Application ${input.appId} is not allowed to perform enhancement getAllergyList, please update the application manifest & get it approved.`,
            );
          }
          this.validateResource(input.payload);
          if (didAppReachLimit(input.appId, this.appAllergyListActionsLimiter)) {
            throw new RateLimitError(
              "Reached enhancements quota, You're not allowed to execute more than 10 enhancements in a minute, please try again later.",
            );
          }

          return await this.adapterManager.resourceEnhancementsManager.getPatientAllergyList(input);
        },
      },
      [PatientEnhancements.GET_LAB_RESULTS]: {
        executeEnhancement: async (input) => {
          const patientPermissions = input.manifest?.EHR.resourcePermissions?.[EHRResource.patient];
          if (!patientPermissions?.labResultsList?.read) {
            throw new UnauthorizedError(
              `Application ${input.appId} is not allowed to perform enhancement getLabResults, please update the application manifest & get it approved.`,
            );
          }
          this.validateResource(input.payload);
          if (didAppReachLimit(input.appId, this.appLabResultsActionsLimiter)) {
            throw new RateLimitError(
              "Reached enhancements quota, You're not allowed to execute more than 10 enhancements in a minute, please try again later.",
            );
          }

          return await this.adapterManager.resourceEnhancementsManager.getPatientLabResults(input);
        },
      },
      [PatientEnhancements.GET_VITALS]: {
        executeEnhancement: async (input) => {
          const patientPermissions = input.manifest?.EHR.resourcePermissions?.[EHRResource.patient];
          if (!patientPermissions?.vitalList?.read) {
            throw new UnauthorizedError(
              `Application ${input.appId} is not allowed to perform enhancement getVitals, please update the application manifest & get it approved.`,
            );
          }
          this.validateResource(input.payload);
          if (didAppReachLimit(input.appId, this.appVitalsActionsLimiter)) {
            throw new RateLimitError(
              "Reached enhancements quota, You're not allowed to execute more than 10 enhancements in a minute, please try again later.",
            );
          }

          return await this.adapterManager.resourceEnhancementsManager.getPatientVitals(input);
        },
      },
    },
  };
}
