import { z } from 'zod/v4';
import { AddressLine, City, FullAddress, State, ZipCode } from '../primitives';

export const AddressSchema = z.object({
  address1: AddressLine.optional(),
  address2: AddressLine.optional(),
  city: City.optional(),
  state: State.optional(),
  zipCode: ZipCode.optional(),
  fullAddress: FullAddress.optional(),
});

export type Address = z.infer<typeof AddressSchema>;
