import { WebConnectors } from '../..';
import { WebConnectorMessageTypes } from '../../enum';
import { CaptureScreenshotInput, CaptureScreenshotResponse } from '../../types';

export async function captureScreenshot(
  this: WebConnectors,
  { uploadUrl }: CaptureScreenshotInput,
): Promise<CaptureScreenshotResponse> {
  return await this.messaging.sendMessage({
    type: WebConnectorMessageTypes.captureScreenshot,
    payload: { uploadUrl },
  });
}
