import { z } from 'zod/v4';
import { AddressSchema } from './address';
import { ContactInfoWithFaxSchema } from './contactInfo';
import { BasicBool, EhrId, NPI, OrgName } from '../primitives';

export const OrganizationSchema = z.object({
  ehrId: EhrId.optional(),
  npi: NPI.optional(),
  name: OrgName.optional(),
  isPrimary: BasicBool.optional(),
  address: AddressSchema.optional(),
  contact_info: ContactInfoWithFaxSchema.optional(),
});
