import { BareboneManager } from '@/barebone-manager';
import { OsFeatureFlagsClient } from '@/infra/featureFlags';
import { LoggerFactory, LoggerGlobalConfig } from '@getvim-os/logger';
import { DITelemetryGlobalAttributes } from '@getvim/opentelemetry-sdk/inversify';
import { createListenerMiddleware } from '@reduxjs/toolkit';
import { Container, inject, injectable } from 'inversify';
import { ReduxListener, RootState } from '..';

export const userLoggedIn = (_action, currentState: RootState, previousState: RootState) => {
  return previousState.userState.user === undefined && currentState.userState.user !== undefined;
};

export const userLoggedOut = (_action, currentState: RootState, previousState: RootState) => {
  return currentState.userState.user === undefined && previousState.userState.user !== undefined;
};

export const userUpdated = (_action, currentState: RootState, previousState: RootState) => {
  return !!(
    currentState.userState.user &&
    previousState.userState.user &&
    currentState.userState.user !== previousState.userState.user
  );
};

export const userAccessTokenChanged = (
  _action,
  currentState: RootState,
  previousState: RootState,
) => {
  return !!(
    currentState.userState.accessToken &&
    currentState.userState.accessToken !== previousState.userState.accessToken
  );
};

@injectable()
export class UserListenerMiddleware implements ReduxListener {
  public listenerMiddleware: ReduxListener['listenerMiddleware'];

  constructor(@inject(Container) container: Container) {
    const listener = createListenerMiddleware<RootState>();
    const logger = container.get(LoggerFactory);
    const log = logger.create('UserListenerMiddleware');

    listener.startListening({
      predicate: userLoggedIn,
      effect: async (_action, api) => {
        const { ehrSystem, slug } = api.getState().userState.organization!;
        const ffClient = container.get(OsFeatureFlagsClient);
        const telemetryGlobalAttributes = container.get(DITelemetryGlobalAttributes);
        const loggerGlobalConfig = container.get(LoggerGlobalConfig);
        ffClient.updateDefaultContext({
          organizationKey: slug,
          adapterName: ehrSystem,
          vimUserEmail: api.getState().userState.user!.email,
        });

        const { linkedEhrUser } = api.getState().userState.user!;
        telemetryGlobalAttributes.updateAttributes({
          linkedEhrUser,
        });
        loggerGlobalConfig.updateMetadata({
          linkedEhrUser,
        });

        const bareboneManager = container.get(BareboneManager);
        await bareboneManager.setVimOsVisible(true);
        log.info('onLogin completed succefully');
      },
    });

    listener.startListening({
      predicate: userLoggedOut,
      effect: async (_action) => {
        const ffClient = container.get(OsFeatureFlagsClient);
        const telemetryGlobalAttributes = container.get(DITelemetryGlobalAttributes);
        ffClient.updateDefaultContext({
          vimUserEmail: undefined,
        });
        telemetryGlobalAttributes.updateAttributes({
          organizationId: undefined,
          ehrSystem: undefined,
          linkedEhrUser: undefined,
        });

        const bareboneManager = container.get(BareboneManager);
        await bareboneManager.setVimOsVisible(false);
        log.info('onLogout completed succefully');
      },
    });

    this.listenerMiddleware = listener.middleware;
  }
}
