import { createListenerMiddleware } from '@reduxjs/toolkit';
import { inject, injectable } from 'inversify';
import { AnalyticsManager } from '.';
import { ReduxListener, RootState } from '@/store';
import { userLoggedIn, userUpdated, userLoggedOut } from '@/store/user/userState.listener';

@injectable()
export class AnalyticsStoreListener implements ReduxListener {
  public listenerMiddleware: ReduxListener['listenerMiddleware'];

  constructor(@inject(AnalyticsManager) analyticsManager: AnalyticsManager) {
    const listener = createListenerMiddleware<RootState>();
    listener.startListening({
      predicate: userLoggedIn,
      effect: (_action, _api) => {
        analyticsManager.setUserId(_api.getState()?.userState?.user?.externalId ?? null);
      },
    });
    listener.startListening({
      predicate: userLoggedOut,
      effect: (_action, _api) => {
        analyticsManager.setUserId(null);
      },
    });
    listener.startListening({
      predicate: userUpdated,
      effect: (_action, _api) => {
        analyticsManager.setUserId(_api.getState()?.userState?.user?.externalId ?? null);
      },
    });
    this.listenerMiddleware = listener.middleware;
  }
}
