import type { VimSpan } from '@getvim/opentelemetry-sdk/client';
import { BareboneToOsMessaging, BareboneManifest } from '@getvim/ehr-sdk-api';

type BareboneMessageTypes = BareboneToOsMessaging.BareboneMessageTypes;

export const PARENT_COMMUNICATOR = Symbol.for('PARENT_COMMUNICATOR');

type EHR_INSTANCE_ID = number;

export type BareboneMessageHandler<T extends BareboneMessageTypes> = (
  message: BareboneToOsMessaging.BareboneMessagePayload[T] & { span: VimSpan },
) => void;

export interface ParentMessage<T = unknown> {
  data: T;
  source: FrameSource;
  ports?: MessagePort[];
}

export type FrameSource = WindowProxy | EHR_INSTANCE_ID | null;

export interface ParentCommunicator {
  setup(ehrInstanceId?: number): Promise<BareboneManifest | void>;
  onParentMessage(callback: (parentMessage: ParentMessage) => void): void;
  sendRawMessage(message: unknown, ports?: ReadonlyArray<MessagePort>): void;
  sendAsyncMessage(message: AsyncMessageToParentPayload): void;
  sendMessage<T = unknown>(
    message: MessageToParentPayload,
    timeout?: number,
    parentSpan?: VimSpan,
  ): Promise<T>;
  sendMessageWithHandler<T>(
    message: MessageToParentPayload,
    handler: (data: T, isError: boolean) => void,
    timeout?: number,
  ): Promise<string>;
  sendMessageWithHandlerPort<T>(
    message: MessageToParentPayload,
    handlerPort: MessagePort,
    timeout?: number,
  ): Promise<T>;
  addBareboneMessageHandler<T extends BareboneMessageTypes>(
    eventType: T,
    handler: BareboneMessageHandler<T>,
  ): void;
}

export interface SendMessageInput {
  type: string;
  payload?: unknown;
  timeout?: number;
  ehrInstanceId?: number;
}

export type AsyncMessageToParentPayload = Omit<MessageToParentPayload, 'type'> & { type?: string };

export interface MessageToParentPayload {
  type: string;
  payload?: unknown;
  messageId: string;
  ehrInstanceId?: number;
}

declare global {
  interface Window {
    // eslint-disable-next-line @typescript-eslint/naming-convention
    $barebonePort?: MessagePort;
  }
}
