import { z } from 'zod/v4';

export const BasicBool = z.boolean().meta({ kind: 'bool' });
export const BasicInt = z.number().int().meta({ kind: 'int' });
export const BasicString = z.string().meta({ kind: 'text' });
export const BasicDate = z.date().meta({
  kind: 'date-object',
  description: 'TypeScript Date object',
});

export const IsoDate = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/)
  .meta({
    kind: 'date',
    examples: ['2025-08-17'],
    description: 'ISO date YYYY-MM-DD',
  });

export const Note = BasicString.meta({ kind: 'note', description: 'Free text medical note' });
