import { z } from 'zod/v4';
import { BasicString } from './primitives';

/** Contact */
export const PhoneNumber = z
  .string()
  .regex(/^\d{3}-\d{3}-\d{4}$/)
  .meta({
    kind: 'phone',
    examples: ['555-123-4567'],
    description: 'Phone/Fax number. 10 digits with dashes, without extension',
  });

export const Email = z.email().meta({
  kind: 'email',
  examples: ['user@example.com'],
  description: 'Email address',
});

/** Address */
export const AddressLine = BasicString.meta({ kind: 'addressLine', examples: ['123 Main St'] });
export const City = BasicString.meta({ kind: 'city', examples: ['Beverly Hills'] });
export const State = BasicString.meta({ kind: 'state', examples: ['CA'] });
export const ZipCode = BasicString.meta({ kind: 'zip', examples: ['90210'] });
export const FullAddress = BasicString.meta({
  kind: 'fullAddress',
  description: 'Full address string',
  examples: ['123 Main St, Beverly Hills, CA 90210'],
});
