import { WebConnectors } from '../..';
import { WebConnectorMessageTypes } from '../../enum';
import { CreateMediaRecorderInput } from '../../types/mediaRecorder';

export async function createAudioMediaRecorder(
  this: WebConnectors,
  { selector, frameSelector, handlerPort, appId, ref }: CreateMediaRecorderInput,
): Promise<{ subscriptionId: string }> {
  return await this.messaging.sendMessageWithHandlerPort(
    {
      type: WebConnectorMessageTypes.createAudioMediaRecorder,
      payload: { selector, frameSelector, appId, ref },
    },
    handlerPort,
  );
}
