import { z } from 'zod/v4';
import { BasicBool, VimEntityTypeEnum } from '../entities';

const SubSectionRequestSchema = z.object({
  read: BasicBool.optional(),
  write: BasicBool.optional(),
});

export const EntitiesRequestSchema = z
  .object({
    [VimEntityTypeEnum.referral]: z.object({
      identifiers: z.optional(SubSectionRequestSchema),
      basicInformation: z.optional(SubSectionRequestSchema),
      conditions: z.optional(SubSectionRequestSchema),
      procedureCodes: z.optional(SubSectionRequestSchema),
      referringProvider: z.optional(SubSectionRequestSchema),
      targetProvider: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.editableReferral]: z.object({
      identifiers: z.optional(SubSectionRequestSchema),
      basicInformation: z.optional(SubSectionRequestSchema),
      conditions: z.optional(SubSectionRequestSchema),
      procedureCodes: z.optional(SubSectionRequestSchema),
      referringProvider: z.optional(SubSectionRequestSchema),
      targetProvider: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.orders]: z.object({
      identifiers: z.optional(SubSectionRequestSchema),
      basicInformation: z.optional(SubSectionRequestSchema),
      assessments: z.optional(SubSectionRequestSchema),
      procedureCodes: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.editableOrder]: z.object({
      basicInformation: z.optional(SubSectionRequestSchema),
      targetProvider: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.encounter]: z.object({
      identifiers: z.optional(SubSectionRequestSchema),
      basicInformation: z.optional(SubSectionRequestSchema),
      encounterNotes: z.optional(SubSectionRequestSchema),
      subjective: z.optional(SubSectionRequestSchema),
      objective: z.optional(SubSectionRequestSchema),
      assessment: z.optional(SubSectionRequestSchema),
      plan: z.optional(SubSectionRequestSchema),
      patientInstructions: z.optional(SubSectionRequestSchema),
      provider: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.editableEncounter]: z.object({
      identifiers: z.optional(SubSectionRequestSchema),
      basicInformation: z.optional(SubSectionRequestSchema),
      encounterNotes: z.optional(SubSectionRequestSchema),
      subjective: z.optional(SubSectionRequestSchema),
      objective: z.optional(SubSectionRequestSchema),
      assessment: z.optional(SubSectionRequestSchema),
      plans: z.optional(SubSectionRequestSchema),
      patientInstructions: z.optional(SubSectionRequestSchema),
      provider: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.patient]: z.object({
      identifiers: z.optional(SubSectionRequestSchema),
      demographics: z.optional(SubSectionRequestSchema),
      address: z.optional(SubSectionRequestSchema),
      contactInformation: z.optional(SubSectionRequestSchema),
      insuranceInfo: z.optional(SubSectionRequestSchema),
      problemList: z.optional(SubSectionRequestSchema),
      pcp: z.optional(SubSectionRequestSchema),
    }),
    [VimEntityTypeEnum.televisit]: z.object({
      patientId: z.optional(SubSectionRequestSchema),
      type: z.optional(SubSectionRequestSchema),
      status: z.optional(SubSectionRequestSchema),
    }),
  })
  .partial();

export type EntitiesRequest = z.infer<typeof EntitiesRequestSchema>;
