import { ListenerPredicate, OsState, RootState, addListener } from '@/store';
import { selectIsAnyAppListeningToAudio } from '@/store/selectors/appListening.selectors';
import {
  selectAllNotificationsCleared,
  selectTotalNotifications,
} from '@/store/selectors/appNotificationBadge.selectors';
import { selectShowUi } from '@/store/selectors/showUi.selectors';
import { BareboneMessaging } from '@getvim-os/barebone/infra';
import { Logger, LoggerFactory } from '@getvim-os/logger';
import { BareboneManifest, OSToBareboneMessaging } from '@getvim/ehr-sdk-api';
import { VimTracer } from '@getvim/opentelemetry-sdk/client';
import { DIVimTracerProvider } from '@getvim/opentelemetry-sdk/inversify';
import { Attributes } from '@opentelemetry/api';
import { inject, injectable, interfaces } from 'inversify';
import { BAREBONE_MANIFEST } from './injectTokens';

const OSMessageTypes = OSToBareboneMessaging.osMessageTypesSchema.enum;

type HubStatus = 'ENABLED' | 'LOADING' | 'DISABLED';

type OSMessagePayload<T extends OSToBareboneMessaging.OSMessageTypes> =
  OSToBareboneMessaging.OSMessagePayload[T];

type BadgeStatus = {
  count?: number;
  dot?: boolean;
};

const calcHubStatus = (state: RootState): HubStatus => {
  const applications = state.applicationsState?.applications || {};
  const isEnabled = Object.values(applications).some((app) => !app.disabled && !app.loading);
  if (isEnabled) {
    return 'ENABLED';
  }
  const isLoading = Object.values(applications).some((app) => app.loading);
  if (isLoading) {
    return 'LOADING';
  }
  return 'DISABLED';
};

const calcBadgeStatus = (state: RootState): BadgeStatus => {
  const totalNotifications = selectTotalNotifications(state);
  const allNotificationsCleared = selectAllNotificationsCleared(state);

  // If all notifications are cleared, show no notifications
  if (allNotificationsCleared) {
    return {};
  }

  // If there are notifications, show the count
  if (totalNotifications > 0) {
    return { count: totalNotifications };
  }

  // If total is 0, we only show a dot
  return { dot: true };
};

const openStatusChanged: ListenerPredicate = (_action, currentState, previousState) => {
  const hasCurrentSelectedApp =
    !!currentState.applicationsState?.selectedApplication?.selectedAppId;
  const hadPreviousSelectedApp =
    !!previousState.applicationsState?.selectedApplication?.selectedAppId;
  return hasCurrentSelectedApp !== hadPreviousSelectedApp;
};

const enabledStatusChanged: ListenerPredicate = (_action, currentState, previousState) => {
  const previousStatus = calcHubStatus(previousState);
  const currentStatus = calcHubStatus(currentState);
  return currentStatus !== previousStatus;
};

const audioListeningStatusChanged: ListenerPredicate = (_action, currentState, previousState) => {
  const previousListeningStatus = selectIsAnyAppListeningToAudio(previousState);
  const currentListeningStatus = selectIsAnyAppListeningToAudio(currentState);
  return currentListeningStatus !== previousListeningStatus;
};

const badgeStatusChanged: ListenerPredicate = (_action, currentState, previousState) => {
  const previousBadgeStatus = calcBadgeStatus(previousState);
  const currentBadgeStatus = calcBadgeStatus(currentState);

  // Check if count changed
  if (previousBadgeStatus.count !== currentBadgeStatus.count) {
    return true;
  }

  // Check if dot status changed
  if (previousBadgeStatus.dot !== currentBadgeStatus.dot) {
    return true;
  }

  return false;
};

const uiIsReadyToDisplay: ListenerPredicate = (_action, currentState, previousState) => {
  const previousIsNoReadyToDisplay = selectShowUi(previousState);
  const currentIsReadyToDisplay = selectShowUi(currentState);
  return !previousIsNoReadyToDisplay && currentIsReadyToDisplay;
};

@injectable()
export class BareboneHubStateNotifier {
  private tracer: VimTracer;
  private logger: Logger;
  constructor(
    @inject(OsState) private osState: OsState,
    @inject(BAREBONE_MANIFEST) bareboneManifest: BareboneManifest,
    @inject(BareboneMessaging) public messaging: BareboneMessaging,
    @inject(LoggerFactory) loggerFactory: LoggerFactory,
    @inject(DIVimTracerProvider) private traceProvider: DIVimTracerProvider,
  ) {
    this.logger = loggerFactory.create('BareboneHubStateNotifier');
    this.tracer = this.traceProvider.getTracer('BareboneHubStateNotifier');

    const currentState = this.osState.store.getState();
    const isAlreadyReadyToDisplay = selectShowUi(currentState);

    if (isAlreadyReadyToDisplay) {
      this.sendUiReadyToDisplayMessage();
    } else {
      this.osState.store.dispatch(
        addListener({
          predicate: uiIsReadyToDisplay,
          effect: (_, listenerApi) => {
            this.sendUiReadyToDisplayMessage();
            listenerApi.unsubscribe();
          },
        }),
      );
    }

    /**
     * Listener for hub open status changes.
     * Open status changes to true when an app is selected after no app was previously selected.
     * Open status changes to false when no app is selected after an app was previously selected.
     * In such a case we send a message to the barebone so that it knows to change the hub open status
     */

    if (bareboneManifest.hub?.handleOpenStatus) {
      this.osState.store.dispatch(
        addListener({
          predicate: openStatusChanged,
          effect: async (_action, api) => {
            const shouldBeOpen =
              !!api.getState().applicationsState?.selectedApplication?.selectedAppId;
            try {
              await this.notifyBarebone(OSMessageTypes.SET_HUB_OPEN_STATUS, {
                status: shouldBeOpen ? 'OPEN' : 'CLOSE',
              });
            } catch {
              // fail silently
            }
          },
        }),
      );
    }
    /**
     * Listener for hub enabled status changes.
     * Enabled status is 'ENABLED' when any app is enabled.
     * Enabled status is 'LOADING' when no app is enabled, but an app is loading.
     * Enabled status is 'DISABLED' when no app is neither enabled nor loading.
     * When the enabled status changes, we send a message to the barebone
     * so that it knows to change the hub enabled status
     */
    if (bareboneManifest.hub?.handleEnabledStatus) {
      this.osState.store.dispatch(
        addListener({
          predicate: enabledStatusChanged,
          effect: async (_action, api) => {
            const status = calcHubStatus(api.getState());
            try {
              await this.notifyBarebone(OSMessageTypes.SET_HUB_ENABLED_STATUS, {
                status,
              });
            } catch {
              // fail silently
            }
          },
        }),
      );
    }

    /**
     * Listener for app audio listening status changes.
     * App listening status changes when:
     * - An app's isListeningToAudio property changes
     * - An app's isMicrophoneBadgeManuallySet property changes
     * - The televisit status changes (which affects whether apps are considered to be listening)
     * When the listening status changes, we send a message to the barebone
     * so that it knows to update the app listening status
     */
    if (bareboneManifest.hub?.handleMicrophoneBadge) {
      this.osState.store.dispatch(
        addListener({
          predicate: audioListeningStatusChanged,
          effect: async (_action, api) => {
            const show = selectIsAnyAppListeningToAudio(api.getState());
            try {
              await this.notifyBarebone(OSMessageTypes.SET_MICROPHONE_BADGE, {
                show,
              });
            } catch {
              // fail silently
            }
          },
        }),
      );
    }

    if (bareboneManifest.hub?.handleNotificationBadge) {
      this.osState.store.dispatch(
        addListener({
          predicate: badgeStatusChanged,
          effect: async (_action, api) => {
            const status = calcBadgeStatus(api.getState());
            try {
              await this.notifyBarebone(OSMessageTypes.SET_NOTIFICATION_BADGE, status);
            } catch {
              // fail silently
            }
          },
        }),
      );
    }
  }

  private sendUiReadyToDisplayMessage = () => {
    this.notifyBarebone(OSMessageTypes.HUB_UI_READY_TO_DISPLAY, {
      status: 'READY',
    }).catch(() => {
      // fail silently
    });
  };

  private notifyBarebone = async <T extends OSToBareboneMessaging.OSMessageTypes>(
    type: T,
    payload: OSMessagePayload<T>,
    traceAttributes: Attributes = payload as Attributes,
  ) => {
    try {
      await this.tracer.startAutoRootSpan(
        `barebone-notifier-${type}`,
        {
          attributes: traceAttributes,
        },
        async () => {
          const res = await this.messaging.sendAwaitedMessage({
            type,
            payload,
            sender: 'vim-os',
          });
          if (res?.error) {
            throw res.error;
          }
          return res;
        },
      );
    } catch (error: unknown) {
      this.logger.warning(`Barebone notifier error on ${type}`, {
        error,
        payload,
      });
      throw error;
    }
  };
}

export const BareboneHubStateNotifierFactory = Symbol('Factory<BareboneHubStateNotifier>');

export type BareboneHubStateNotifierDynamicArgs = [BareboneManifest];

export type BareboneHubStateNotifierFactory = interfaces.SimpleFactory<
  BareboneHubStateNotifier,
  BareboneHubStateNotifierDynamicArgs
>;

/**
 * Factory function to create BareboneHubStateNotifier instances dynamically
 *
 * This factory pattern is used to create the BareboneHubStateNotifier only after
 * the barebone manager has received the manifest. This enables lazy initialization
 * where the notifier is not created until the manifest is available. The factory:
 *
 * 1. Creates a child dependency injection container to isolate the instance
 * 2. Binds the specific bareboneManifest to the BAREBONE_MANIFEST token
 * 3. Resolves the BareboneHubStateNotifier with the injected manifest
 *
 * This ensures the notifier is only instantiated when the barebone manager has
 * the necessary manifest information, preventing premature initialization and
 * ensuring the notifier has access to the correct manifest configuration.
 *
 * @param container - The parent DI container to create a child from
 * @param bareboneManifest - The specific manifest for this barebone instance
 * @returns A configured BareboneHubStateNotifier instance
 */
export const createBareboneHubStateNotifier = (
  container: interfaces.Container,
  bareboneManifest: BareboneManifest,
): BareboneHubStateNotifier => {
  const childContainer = container.createChild();
  childContainer.bind<BareboneManifest>(BAREBONE_MANIFEST).toConstantValue(bareboneManifest);

  return childContainer.get(BareboneHubStateNotifier);
};
