import { createSelector } from '@reduxjs/toolkit';
import { RootState } from '..';
import { InjectedApplication } from '@/hub/types/application';

/**
 * Base selector to get the televisit state from the pending EHR state
 * @param state - The root Redux state
 * @returns The televisit state object
 */
const selectTelevisitState = (state: RootState) => state.pendingEhrState?.televisit;

/**
 * Base selector to get all applications from the applications state
 * @param state - The root Redux state
 * @returns Record of all applications keyed by application ID
 */
const selectApplicationsState = (state: RootState) => state.applicationsState.applications;

/**
 * Base selector to get all user's applications from the state
 * Useful to ensure applications were loaded for the user
 * @param state - The root Redux state
 * @returns Array of all appstore applications
 */
const selectUserApplicationsState = (state: RootState) =>
  state.userState.user?.appStoreApplications;

/**
 * Memoized selector to get the televisit playing status from the pending EHR state
 * @param state - The root Redux state
 * @returns boolean indicating if televisit is currently playing
 */
export const selectIsTelevisitPlaying = createSelector(
  [selectTelevisitState],
  (televisit) => televisit?.status === 'in_progress',
);

/**
 * Memoized selector to get all applications from the applications state
 * @param state - The root Redux state
 * @returns Record of all applications keyed by application ID
 */
export const selectApplications = createSelector(
  [selectApplicationsState],
  (applications) => applications,
);

export const selectUserApplicationIds = createSelector(
  selectUserApplicationsState,
  (applications) => applications?.map((app) => app.metadata.id),
);

/**
 * Factory function to create a memoized selector for a specific application
 * This provides better performance by creating a selector that only depends on the specific app
 * Use this when you frequently access the same app and want optimal memoization
 * @param appId - The application ID to create a selector for
 * @returns A memoized selector for the specific application
 */
export const createSelectApplicationById = (appId: string) =>
  createSelector([selectApplicationsState], (applications) => applications[appId]);

/**
 * Optimized selector that creates a memoized selector for a specific app on-demand
 * This provides the best performance for frequently accessed applications
 * Only recalculates when the specific app changes, not when any app changes
 * @param state - The root Redux state
 * @param appId - The application ID to retrieve
 * @returns The application object or undefined if not found
 */
const appSelectorsCache = new Map<string, ReturnType<typeof createSelectApplicationById>>();

export const selectApplicationById = (state: RootState, appId: string) => {
  if (!appSelectorsCache.has(appId)) {
    appSelectorsCache.set(appId, createSelectApplicationById(appId));
  }
  return appSelectorsCache.get(appId)!(state);
};

/**
 * Helper function to determine if an app is listening to audio
 * This encapsulates the same logic as the isAppListeningToAudio function in the hook
 * @param isTelevisitPlaying - Whether televisit is currently playing
 * @param application - The application to check
 * @returns boolean indicating if the app is listening to audio
 */
const isAppListeningToAudio = (
  isTelevisitPlaying: boolean,
  application: InjectedApplication | undefined,
): boolean => {
  return !!(
    application &&
    (application.isMicrophoneBadgeManuallySet ||
      (isTelevisitPlaying && application.isListeningToAudio))
  );
};

/**
 * Memoized selector to check if a specific app is listening to audio
 * @param state - The root Redux state
 * @param appId - The application ID to check
 * @returns boolean indicating if the specific app is listening to audio
 */
export const selectIsAppListeningToAudio = createSelector(
  [selectIsTelevisitPlaying, selectApplicationById],
  (isTelevisitPlaying, application) => isAppListeningToAudio(isTelevisitPlaying, application),
);

/**
 * Memoized selector to check if any app is listening to audio
 * @param state - The root Redux state
 * @returns boolean indicating if any app is listening to audio
 */
export const selectIsAnyAppListeningToAudio = createSelector(
  [selectIsTelevisitPlaying, selectApplications],
  (isTelevisitPlaying, applications) =>
    Object.values(applications).some((app) => isAppListeningToAudio(isTelevisitPlaying, app)),
);
