import { z } from 'zod/v4';
import { BasicInt, BasicString, IsoDate, NdcCode } from '../primitives';

export const MedicationSchema = z.object({
  basicInformation: z.object({
    medicationName: BasicString.meta({
      description:
        'The base name of the medication, excluding strength, quantity, and other details',
      examples: ['Metformin', 'Lisinopril', 'Aspirin', 'Amoxicillin', 'Atorvastatin'],
    }),
    ndcCode: NdcCode.optional().meta({
      description:
        'National Drug Code - unique identifier for this specific medication formulation',
      examples: ['00378-6205-93', '50090-3568-0', '68382-0843-01'],
    }),
  }),
  dosage: z.object({
    strength: z
      .object({
        value: BasicString.meta({
          description:
            'Amount or range of the active ingredient (e.g., 0.1 mg, 1 tablet, 2 mg/mL, 10 mg, 10 - 20 mg)',
          examples: ['10 mg', '500 mg', '2 mg/mL', '10-20 mg', '0.1 mg', '1 tablet'],
        }),
      })
      .optional(),
    quantity: z
      .object({
        value: BasicInt.optional().meta({
          description: 'Total amount prescribed',
          examples: [30, 60, 90, 120, 15],
        }),
        unit: BasicString.optional().meta({
          description: 'Unit for the prescribed amount (e.g., tablets, capsules, mL)',
          examples: ['tablets', 'capsules', 'mL', 'grams', 'units'],
        }),
      })
      .optional(),
    form: z
      .object({
        unit: BasicString.meta({
          description: 'Physical form of the medication',
          examples: ['tablet', 'capsule', 'solution', 'cream', 'injection', 'patch'],
        }),
      })
      .optional(),
  }),

  /***
   *
   * Coming soon 🔮
   * If you implement those fields in your adapter, please add them under FF and get Vim-OS approval before opening in prod
   *
   * TODO: make administration/timeline/documentation sub-entities required, with sub-fields optional
   *
   ***/
  administration: z
    .object({
      route: BasicString.optional().meta({
        description: 'How the medication should be administered (e.g., oral, nasal, transdermal)',
        examples: ['oral', 'nasal', 'transdermal', 'intravenous', 'topical', 'sublingual'],
      }),
      frequency: BasicString.optional().meta({
        description: 'How often to take the medication (e.g., daily, twice a day, as needed)',
        examples: [
          'daily',
          'twice a day',
          'as needed',
          'every 6 hours',
          'three times a day',
          'once weekly',
        ],
      }),
      take: BasicString.optional().meta({
        description:
          'Special instructions for taking the medication (e.g., with food/milk, before/after meals)',
        examples: [
          'with food',
          'before meals',
          'at bedtime',
          'with milk',
          'after meals',
          'on empty stomach',
        ],
      }),
    })
    .optional(),
  timeline: z
    .object({
      startDate: IsoDate.optional().meta({
        description: 'When the medication regimen begins (YYYY-MM-DD)',
        examples: ['2025-08-17', '2024-12-01', '2025-01-15'],
      }),
      endDate: IsoDate.optional().meta({
        description: 'When the medication regimen ends (YYYY-MM-DD)',
        examples: ['2025-09-17', '2025-01-01', '2025-02-15'],
      }),
      duration: BasicInt.optional().meta({
        description: 'Number of days between start and end dates',
        examples: [30, 90, 7, 14, 180],
      }),
      status: BasicString.optional().meta({
        description: 'Current state of the prescription (e.g., active, inactive, historical)',
        examples: ['active', 'inactive', 'historical', 'discontinued', 'completed'],
      }),
    })
    .optional()
    .meta({
      description: 'When the medication should be taken',
    }),
  documentation: z
    .object({
      reportedBy: BasicString.optional().meta({
        description: 'Healthcare provider who prescribed or recorded the medication',
        examples: ['Dr. Smith', 'Dr. Jane Johnson', 'Provider ID: 12345'],
      }),
      notes: BasicString.optional().meta({
        description: 'Additional instructions or comments about the medication',
        examples: [
          'Monitor blood pressure weekly',
          'May cause drowsiness',
          'Avoid alcohol while taking this medication',
        ],
      }),
      unstructured: BasicString.optional().meta({
        description:
          'Original free-text description if medication was entered as unstructured data in EHR',
        examples: [
          'Metformin 500mg PO BID with meals',
          'Lisinopril 10mg daily for hypertension',
          'Amoxicillin 500mg TID x 7 days',
        ],
      }),
    })
    .optional()
    .meta({
      description: 'Additional clinical context and notes',
    }),
});

export type Medication = z.infer<typeof MedicationSchema>;
