import { z } from 'zod/v4';
import { CodeDescription, ProcedureCode } from '../primitives';

export const ProcedureSchema = z.object({
  code: ProcedureCode.optional(),
  name: CodeDescription.optional(),
});

export type Procedure = z.infer<typeof ProcedureSchema>;

export const ProcedureWithCodeSchema = ProcedureSchema.extend({
  code: ProcedureCode,
});

export type ProcedureWithCode = z.infer<typeof ProcedureWithCodeSchema>;
