import { createSelector } from '@reduxjs/toolkit';
import { RootState } from '..';

const selectUser = (state: RootState) => state?.userState?.user;
const selectOrganization = (state: RootState) => state?.userState?.organization;

export const selectShowUi = createSelector([selectUser, selectOrganization], (user, organization) =>
  Boolean(user?.externalId && organization?.id),
);
