import { z } from 'zod/v4';
import { CodeDescription, Note, DiagnosisCode } from '../primitives';

export const DiagnosisSchema = z.object({
  description: CodeDescription,
  code: DiagnosisCode,
  note: Note.optional(),
});

export type Diagnosis = z.infer<typeof DiagnosisSchema>;

export const DiagnosisSchemaWithNameSchema = DiagnosisSchema.pick({
  code: true,
}).extend({
  code: DiagnosisCode.optional(),
  name: CodeDescription.optional(),
});

export type DiagnosisSchemaWithName = z.infer<typeof DiagnosisSchemaWithNameSchema>;
