import { z } from 'zod/v4';
import { Email, PhoneNumber } from '../primitives';

export const BaseContactInfoSchema = z.object({
  homePhoneNumber: PhoneNumber.optional(),
  mobilePhoneNumber: PhoneNumber.optional(),
  email: Email.optional(),
});

export type BaseContactInfo = z.infer<typeof BaseContactInfoSchema>;

export const ContactInfoWithFaxSchema = BaseContactInfoSchema.extend({
  faxNumber: PhoneNumber.optional(),
});

export type ContactInfoWithFax = z.infer<typeof ContactInfoWithFaxSchema>;
